
from pathlib import Path
import subprocess
import sys
import pandas as pd

root = Path(r"D:\PlaneBasedSLAM\experiments")
data_dir = root / "data" / "bad_match_rejection" / "real"
results_dir = root / "results" / "bad_match_rejection" / "real"
out = results_dir / "prepared_28_only"

manifest = pd.read_csv(
    data_dir / "case_manifest_EVALUATION_METADATA.csv"
)
cases = pd.read_csv(results_dir / "case_results.csv")
decisions = pd.read_csv(results_dir / "match_decisions.csv")

# Use ONLY the cases generated by the latest Prepare.
ids = set(manifest["prepared_case_id"].astype(str))

cases = cases[
    cases["prepared_case_id"].astype(str).isin(ids)
].copy()

decisions = decisions[
    decisions["prepared_case_id"].astype(str).isin(ids)
].copy()

expected_cases = len(ids) * 5
expected_decisions = int(manifest["n_assigned"].sum()) * 5

if (
    len(cases) != expected_cases
    or len(decisions) != expected_decisions
):
    raise RuntimeError(
        f"Incomplete results: {len(cases)} cases, "
        f"{len(decisions)} decisions. Expected "
        f"{expected_cases} and {expected_decisions}."
    )

if set(cases["prepared_case_id"].astype(str)) != ids:
    raise RuntimeError("Some prepared cases are missing")

if cases.duplicated(["prepared_case_id", "method"]).any():
    raise RuntimeError("Duplicate method-case results")

if decisions.duplicated(
    ["prepared_case_id", "method", "pair_index"]
).any():
    raise RuntimeError("Duplicate match decisions")

# Save filtered results without changing original outputs.
out.mkdir(parents=True, exist_ok=True)

cases.to_csv(out / "case_results.csv", index=False)
decisions.to_csv(out / "match_decisions.csv", index=False)

print(
    f"Selected {len(cases)} method-case records "
    f"and {len(decisions)} decisions."
)

# Execute the existing analysis; NO algorithms rerun.
analysis = (
    root / "bad_match_rejection_real"
    / "analyse_bad_match_rejection_real.py"
)

subprocess.run(
    [
        sys.executable,
        str(analysis),
        "--results-dir", str(out),
        "--labels",
        str(data_dir / "labels_EVALUATION_ONLY.csv"),
    ],
    check=True,
)

print(f"\nFinal summary: {out / 'real_summary.csv'}")
